#include <stdio.h>

/* ovosNaCesta mostra a cesta depois de cada ovo posto. A cesta comeca com
   9 ovos e recebe mais tres, um de cada vez. Os tres printf ja estao na
   ordem: escreva, antes de cada um, o ++ que soma UM ovo ao contador. */
void ovosNaCesta(void) {
    int ovos = 9;

    /* primeiro ovo: some um a ovos, de um em um */
    printf("ovos na cesta: %d\n", ovos);

    /* segundo ovo */
    printf("ovos na cesta: %d\n", ovos);

    /* terceiro ovo */
    printf("ovos na cesta: %d\n", ovos);
}

