#include <stdio.h>

/* teste do desafio ovos-na-cesta — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste (modelo cenario-do-harness):
   freopen manda o stdout para o arquivo temporario, o teste chama a funcao
   do aluno e le o arquivo de volta — stdlib puro, sem runner proprio. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void ovosNaCesta(void);

SM_TEST(a_cesta_depois_de_cada_ovo) {
    /* captura: o stdout vira o arquivo sm_saida.tmp */
    freopen("sm_saida.tmp", "w", stdout);
    ovosNaCesta();
    fflush(stdout);

    /* leitura linha a linha: um passo de um por linha */
    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a cesta depois do primeiro ovo", linha, "ovos na cesta: 10\n",
              "a cesta comeca com 9 e o primeiro ++ leva a 10");
    fgets(linha, 80, f);
    checa_str("a cesta depois do segundo ovo", linha, "ovos na cesta: 11\n",
              "cada ++ anda exatamente uma casa: 10 vira 11");
    fgets(linha, 80, f);
    checa_str("a cesta depois do terceiro ovo", linha, "ovos na cesta: 12\n",
              "tres ovos, tres passos de um: 9 mais 3 sao 12");
    /* a saida TERMINA na terceira linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "sao tres ovos: nenhuma quarta linha e aceita");
    fclose(f);
}

solutionCode:
#include <stdio.h>

void ovosNaCesta(void) {
    int ovos = 9;
    ovos++;
    printf("ovos na cesta: %d\n", ovos);
    ovos++;
    printf("ovos na cesta: %d\n", ovos);
    ovos++;
    printf("ovos na cesta: %d\n", ovos);
}
